import os
import json

# Load grids from the session log
d = os.environ['RLM_SESSION_DIR']
fullname = d+'/../../sessions/'+os.path.basename(d)+'.jsonl'
t = open(fullname).read().replace('\\n','\n')

# Simple parser for grids
def parse_grid(name, lines, expected_rows):
    found = False
    grid_str = []
    for line in lines:
        if ' ' not in line and line.strip().replace('\\n','').strip():
            grid_str.append(line)
        if found:
            if not grid_str[-1].strip() and len(grid_str) >= expected_rows:
                break
            if len(grid_str) >= expected_rows + 1:
                break
    return grid_str[:expected_rows]

# Extract just the test input
lines = t.split('\n')
test_rows = []
for line in lines:
    if 'Test input' in line:
        parser = True
    if parser:
        if not line.strip() or all(c in '[]' for c in line):
            if test_rows:
                break
        test_rows.append(line)

print("=== TEST INPUT ===")
print('\n'.join(test_rows[:10]))
